// Руками не править. Исходники раздачи - на рабочем столе, «Упаковка - метод».
// Файлы лежат base64, потому что материал платный: через public они были бы
// доступны по прямой ссылке в обход гейта.

export interface PotokFile {
  key: string;
  /** имя, под которым файл скачается */
  name: string;
  mime: string;
  /** подпись кнопки */
  label: string;
  /** зачем этот файл */
  note: string;
  bytes: number;
  b64: string;
}

// Правила доступа тут НЕ живут: у ветки своя роль «potok» плюс вход по курсу,
